
using System;
using System.Collections.Generic;

namespace AuthDemo.Models;

public class Billing
{
    // =====================================================
    // PRIMARY KEY
    // =====================================================

    public int Id { get; set; }

    // =====================================================
    // INVOICE NUMBER
    // Generated by backend after saving the bill.
    // =====================================================

    public string? InvoiceNumber { get; set; }

    // =====================================================
    // BILL TYPE
    // OP / Lab / Pharmacy
    // =====================================================

    public string BillingType { get; set; } = "OP";

    // =====================================================
    // APPOINTMENT
    // =====================================================

    public int AppointmentId { get; set; }

    public Appointment? Appointment { get; set; }

    // =====================================================
    // PATIENT
    // =====================================================

    public int PatientId { get; set; }

    public Patient? Patient { get; set; }

    // =====================================================
    // DOCTOR
    // =====================================================

    public int DoctorId { get; set; }

    public Doctor? Doctor { get; set; }

    // =====================================================
    // HOSPITAL
    // =====================================================

    public int HospitalId { get; set; }

    public Hospital? Hospital { get; set; }

    // =====================================================
    // BRANCH
    // =====================================================

    public int? BranchId { get; set; }

    public Branch? Branch { get; set; }

    // =====================================================
    // BILL AMOUNTS
    // =====================================================

    public decimal ConsultationCharge { get; set; }

    public decimal LabCharge { get; set; }

    public decimal MedicineCharge { get; set; }

    public decimal SubTotal { get; set; }

    // =====================================================
    // DISCOUNT
    // =====================================================

    // Existing discount percentage.
    // Example: 10 means 10%.
    public decimal Discount { get; set; }

    // Actual discount amount in rupees.
    public decimal DiscountAmount { get; set; }

    // Amount after applying discount.
    public decimal TaxableAmount { get; set; }

    // =====================================================
    // GST
    // =====================================================

    // Total applicable GST percentage.
    public decimal GstPercentage { get; set; }

    // Existing total GST amount.
    public decimal GstAmount { get; set; }

    // None / CGST_SGST / IGST
    public string TaxType { get; set; } = "None";

    // Central GST
    public decimal CgstPercentage { get; set; }

    public decimal CgstAmount { get; set; }

    // State GST
    public decimal SgstPercentage { get; set; }

    public decimal SgstAmount { get; set; }

    // Integrated GST
    public decimal IgstPercentage { get; set; }

    public decimal IgstAmount { get; set; }

    // =====================================================
    // FINAL BILL AMOUNT
    // =====================================================

    public decimal TotalAmount { get; set; }

    // =====================================================
    // PAYMENT
    // =====================================================

    public string PaymentMode { get; set; } = "Cash";

    // Pending / Paid
    public string Status { get; set; } = "Pending";

    // =====================================================
    // PAYMENT TRANSACTIONS
    // =====================================================

    public ICollection<BillingPaymentTransaction>
        PaymentTransactions
    { get; set; }
        = new List<BillingPaymentTransaction>();

    // =====================================================
    // CREATED DATE
    // =====================================================

    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
}
